#!/usr/bin/env python3
"""Emit identical static image-delivery fixtures with different native attributes."""
from pathlib import Path
root=Path(__file__).resolve().parents[1]/'kits/shorts-lab/effects'
def picture(scene,hero,selective):
 loading='eager' if hero or not selective else 'lazy'
 priority=' fetchpriority="high"' if hero and selective else ''
 suffix=f'?scene={scene}'
 return f'''<picture><source type="image/avif" srcset="./assets/delivery-600.avif{suffix} 600w, ./assets/delivery-1200.avif{suffix} 1200w" sizes="(max-width:700px) 100vw, {960 if hero else 480}px"><source type="image/webp" srcset="./assets/delivery-600.webp{suffix} 600w, ./assets/delivery-1200.webp{suffix} 1200w" sizes="(max-width:700px) 100vw, {960 if hero else 480}px"><img {'id="delivery-hero"' if hero else ''} src="./assets/delivery-1200.jpg{suffix}" srcset="./assets/delivery-600.jpg{suffix} 600w, ./assets/delivery-1200.jpg{suffix} 1200w" sizes="(max-width:700px) 100vw, {960 if hero else 480}px" width="1200" height="800" alt="Original illustrated landscape, {('hero' if hero else 'project '+str(scene))}" loading="{loading}" decoding="async"{priority}></picture>'''
for selective in (True,False):
 name='image-delivery.html' if selective else 'image-delivery-eager.html'
 title='Selective loading' if selective else 'All-eager baseline'
 gallery=''.join(f'<figure>{picture(i,False,selective)}<figcaption>Original project illustration {i}</figcaption></figure>' for i in range(1,5))
 sections=''.join(f'<section class="long-section"><h2>{title}</h2><p>This long-form fixture deliberately puts its gallery well below the initial viewport. Its layout and image bytes are identical across the comparison. A browser chooses its own lazy-loading proximity threshold.</p><p>Scroll normally to bring the project gallery into view. Intrinsic dimensions reserve each image’s geometry.</p></section>' for title in ['The same content','A measured comparison','A gallery further down'])
 html=f'''<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} · Motion Atlas</title><style>*{{box-sizing:border-box}}body{{margin:0;background:#14252b;color:#eaf7f0;font:1rem/1.6 system-ui,sans-serif}}main{{max-width:1008px;padding:24px;margin:auto}}a{{color:#b8edcf}}nav{{display:flex;gap:20px;flex-wrap:wrap}}h1{{font-size:clamp(1.8rem,5vw,3rem);line-height:1.1}}picture,img{{display:block;width:100%;height:auto}}picture{{background:#244c40;aspect-ratio:3/2}}figure{{margin:0}}.long-section{{min-height:1500px;padding-top:48px}}.gallery{{display:grid;grid-template-columns:1fr 1fr;gap:20px}}summary{{cursor:pointer;min-height:44px}}pre{{white-space:pre-wrap;overflow-wrap:anywhere;font-size:.875rem}}:focus-visible{{outline:3px solid #ffb28b;outline-offset:3px}}@media(max-width:700px){{.gallery{{grid-template-columns:1fr}}}}</style><script src="./delivery-observer.js" defer></script></head><body><main><nav><a href="./">Reusable effects</a><a href="./{'image-delivery-eager.html' if selective else 'image-delivery.html'}">{'Compare all-eager baseline' if selective else 'Compare selective loading'}</a></nav><h1>A landscape worth discovering.</h1><p>{title}: one discoverable hero, a long article and four project illustrations.</p>{picture(0,True,selective)}<details><summary>Measured browser data and markup</summary><pre data-delivery-metrics>Measurements are collected in this browser; no performance gain is assumed.</pre><pre>&lt;img width="1200" height="800" loading="eager" {'fetchpriority="high"' if selective else 'fetchpriority="auto"'}&gt;\nGallery: loading="{'lazy' if selective else 'eager'}". Picture/srcset selects AVIF, WebP or JPEG.</pre><p>Priority is a hint; lazy loading controls eligibility. The likely LCP hero is never lazy-loaded. LCP/CLS are reported only where this engine exposes them.</p></details>{sections}<section class="gallery" aria-label="Project gallery">{gallery}</section><p><a href="./">Return to library</a></p></main></body></html>'''
 (root/name).write_text(html)
